const grid=document.querySelector('#collection-grid'),viewer=document.querySelector('#media-viewer'),content=document.querySelector('#viewer-content');
let kind='all',category='all',shown=24,current=0,selection=[];
const duration=seconds=>seconds<1?'<1 sec':Math.floor(seconds/60)+':'+String(Math.floor(seconds%60)).padStart(2,'0');
const photos=galleryMedia.filter(m=>m.type==='photo').length,videos=galleryMedia.length-photos;
document.querySelector('#collection-counts').textContent=`${photos} photographs  /  ${videos} videos  /  One Eden`;
function render(){selection=galleryMedia.filter(m=>(kind==='all'||m.type===kind)&&(category==='all'||m.category===category));grid.replaceChildren();selection.slice(0,shown).forEach((m,i)=>{const card=document.createElement('button');card.type='button';card.className='media-card';card.setAttribute('aria-label',(m.type==='video'?'Play video: ':'View photo: ')+m.title);const thumb=document.createElement('span');thumb.className='media-thumbnail';const img=document.createElement('img');img.src=m.poster||m.src;img.alt=m.title;img.loading='lazy';img.decoding='async';thumb.append(img);const badge=document.createElement('span');badge.className='media-badge';badge.textContent=m.type==='video'?'VIDEO · '+duration(m.duration):m.category.toUpperCase();thumb.append(badge);if(m.type==='video'){const play=document.createElement('span');play.className='play-badge';play.setAttribute('aria-hidden','true');play.innerHTML='<b>▶</b>';thumb.append(play);}const label=document.createElement('span');label.className='media-label';const title=document.createElement('span');title.textContent=m.title;const arrow=document.createElement('span');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');label.append(title,arrow);card.append(thumb,label);card.addEventListener('click',()=>{current=i;showMedia();viewer.showModal();document.body.classList.add('dialog-open');});grid.append(card);});document.querySelector('#collection-status').textContent=`Showing ${Math.min(shown,selection.length)} of ${selection.length} items`;document.querySelector('#collection-empty').hidden=selection.length!==0;document.querySelector('#load-more').hidden=shown>=selection.length;}
function showMedia(){content.querySelector('video')?.pause();content.replaceChildren();const m=selection[current];const el=document.createElement(m.type==='video'?'video':'img');el.src=m.src;if(m.type==='video'){el.controls=true;el.playsInline=true;el.preload='metadata';el.poster=m.poster;}else el.alt=m.title;content.append(el);document.querySelector('#viewer-count').textContent=`${current+1} / ${selection.length}`;document.querySelector('#viewer-caption').textContent=m.title;}
function move(delta){current=(current+delta+selection.length)%selection.length;showMedia();}
document.querySelectorAll('[data-kind]').forEach(button=>button.addEventListener('click',()=>{kind=button.dataset.kind;shown=24;document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const select=document.querySelector('#collection-category');if(kind==='video'){category='all';select.value='all';}select.disabled=kind==='video';render();}));
document.querySelector('#collection-category').addEventListener('change',e=>{category=e.target.value;shown=24;render();});document.querySelector('#load-more').addEventListener('click',()=>{shown+=24;render();});
document.querySelector('#viewer-prev').addEventListener('click',()=>move(-1));document.querySelector('#viewer-next').addEventListener('click',()=>move(1));document.querySelector('#viewer-close').addEventListener('click',()=>viewer.close());viewer.addEventListener('close',()=>{content.querySelector('video')?.pause();content.replaceChildren();document.body.classList.remove('dialog-open');});viewer.addEventListener('keydown',e=>{if(e.target.tagName==='VIDEO')return;if(e.key==='ArrowRight'){e.preventDefault();move(1);}if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}});viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close();}});
document.querySelector('#year').textContent=new Date().getFullYear();const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});render();
